import { useId, type ComponentProps } from "react";
import { Badge, type BadgeProps } from "./badge";
import { Button } from "./button";
import { cn } from "./utils";
import type { EntityReference } from "./work-management-types";

type TaskItemStatus = {
    id: string;
    label: string;
    variant?: BadgeProps["variant"];
};

type TaskItemPriority = {
    id: string;
    label: string;
    variant?: BadgeProps["variant"];
};

type TaskDueDate = {
    value: string;
    label: string;
};

type TaskItemAssignee = EntityReference & { kind: "person" };

type TaskItemData = {
    id: string;
    title: string;
    status: TaskItemStatus;
    assignees: readonly TaskItemAssignee[];
    priority: TaskItemPriority | null;
    dueDate: TaskDueDate | null;
    subtaskCount: number;
    blocked: "blocked" | "clear" | "unknown";
};

type TaskItemAction = {
    id: string;
    label: string;
    onSelect: (task: TaskItemData) => void;
    disabled?: boolean;
};

type TaskItemProps = Omit<
    ComponentProps<"article">,
    "children" | "aria-label"
> & {
    task: TaskItemData;
    layout?: "row" | "card";
    onOpen?: (task: TaskItemData) => void;
    actions?: readonly TaskItemAction[];
};

function validateTask(task: TaskItemData) {
    if (!task.id.trim() || !task.title.trim() ||
        !task.status.id.trim() || !task.status.label.trim()) {
        throw new Error("TaskItem requires task, title and status IDs.");
    }
    if (!Number.isInteger(task.subtaskCount) || task.subtaskCount < 0) {
        throw new RangeError("TaskItem subtaskCount must be nonnegative.");
    }
    const assigneeIds = new Set<string>();
    for (const assignee of task.assignees) {
        if (assignee.kind !== "person" || !assignee.id.trim() ||
            !assignee.title.trim()) {
            throw new Error("TaskItem assignees must be named people.");
        }
        if (assigneeIds.has(assignee.id)) {
            throw new Error("TaskItem assignees must have unique IDs.");
        }
        assigneeIds.add(assignee.id);
    }
}

function TaskItem({
    task,
    layout = "row",
    onOpen,
    actions = [],
    className,
    ...props
}: TaskItemProps) {
    const generatedId = useId();
    validateTask(task);
    if (layout !== "row" && layout !== "card") {
        throw new RangeError("TaskItem layout is not supported.");
    }
    const actionIds = new Set<string>();
    for (const action of actions) {
        if (!action.id.trim() || !action.label.trim()) {
            throw new Error("TaskItem actions need IDs and labels.");
        }
        if (actionIds.has(action.id)) {
            throw new Error(`TaskItem action ID is duplicated: ${action.id}`);
        }
        actionIds.add(action.id);
    }
    const headingId = `${generatedId}-title`;
    const blocked = task.blocked === "blocked"
        ? { label: "차단됨", variant: "danger" as const }
        : task.blocked === "clear"
            ? { label: "차단되지 않음", variant: "outline" as const }
            : { label: "차단 상태 미확인", variant: "default" as const };

    return (
        <article {...props} aria-labelledby={headingId}
            data-layout={layout}
            className={cn(
                "@container min-w-0 rounded-sm border border-border " +
                "bg-surface text-foreground",
                layout === "row"
                    ? "grid gap-3 p-[var(--space-3)]"
                    : "grid gap-4 p-[var(--space-4)]",
                className,
            )}>
            <div className={cn(
                "flex min-w-0 flex-wrap items-start justify-between gap-3",
                layout === "row" && "@md:items-center",
            )}>
                <div className="min-w-0 flex-1">
                    <p className="m-0 text-xs text-muted">#{task.id}</p>
                    <h3 id={headingId}
                        className="m-0 mt-1 min-w-0 break-words text-base font-semibold">
                        {onOpen ? (
                            <button type="button"
                                aria-label={`${task.title} 상세 보기`}
                                className={
                                    "text-left hover:underline " +
                                    "focus-visible:outline-2 " +
                                    "focus-visible:outline-focus"
                                }
                                onClick={() => onOpen(task)}>
                                {task.title}
                            </button>
                        ) : task.title}
                    </h3>
                </div>
                {actions.length > 0 && (
                    <div role="group" aria-label={`${task.title} 작업`}
                        className="flex flex-wrap gap-2">
                        {actions.map((action) => (
                            <Button key={action.id} type="button"
                                variant="outline"
                                aria-label={action.label}
                                disabled={action.disabled}
                                onClick={() => action.onSelect(task)}>
                                {action.label}
                            </Button>
                        ))}
                    </div>
                )}
            </div>
            <dl aria-label={`${task.title} 요약`} className={cn(
                "m-0 grid min-w-0 gap-x-[var(--space-4)] " +
                "gap-y-[var(--space-3)]",
                layout === "row"
                    ? "@md:grid-cols-3 @xl:grid-cols-6"
                    : "@sm:grid-cols-2",
            )}>
                <div className="min-w-0">
                    <dt className="text-xs text-muted">상태</dt>
                    <dd className="m-0 mt-1">
                        <Badge variant={task.status.variant ?? "default"}>
                            {task.status.label}
                        </Badge>
                    </dd>
                </div>
                <div className="min-w-0">
                    <dt className="text-xs text-muted">담당자</dt>
                    <dd className="m-0 mt-1">
                        {task.assignees.length ? (
                            <ul aria-label="담당자 목록"
                                className="m-0 flex list-none flex-wrap gap-1 p-0">
                                {task.assignees.map((assignee) => (
                                    <li key={assignee.id}>
                                        <Badge variant="outline">
                                            {assignee.title}
                                        </Badge>
                                    </li>
                                ))}
                            </ul>
                        ) : (
                            <span className="text-sm text-muted">
                                담당자 없음
                            </span>
                        )}
                    </dd>
                </div>
                <div className="min-w-0">
                    <dt className="text-xs text-muted">우선순위</dt>
                    <dd className="m-0 mt-1">
                        {task.priority ? (
                            <Badge variant={task.priority.variant ?? "default"}>
                                {task.priority.label}
                            </Badge>
                        ) : (
                            <span className="text-sm text-muted">
                                우선순위 없음
                            </span>
                        )}
                    </dd>
                </div>
                <div className="min-w-0">
                    <dt className="text-xs text-muted">기한</dt>
                    <dd className="m-0 mt-1 text-sm">
                        {task.dueDate ? (
                            <time dateTime={task.dueDate.value}>
                                {task.dueDate.label}
                            </time>
                        ) : (
                            <span className="text-muted">기한 없음</span>
                        )}
                    </dd>
                </div>
                <div className="min-w-0">
                    <dt className="text-xs text-muted">하위 작업</dt>
                    <dd className="m-0 mt-1 text-sm">
                        {task.subtaskCount}개
                    </dd>
                </div>
                <div className="min-w-0">
                    <dt className="text-xs text-muted">차단 상태</dt>
                    <dd className="m-0 mt-1">
                        <Badge variant={blocked.variant}>
                            {blocked.label}
                        </Badge>
                    </dd>
                </div>
            </dl>
        </article>
    );
}

export { TaskItem };
export type {
    TaskDueDate,
    TaskItemAction,
    TaskItemAssignee,
    TaskItemData,
    TaskItemPriority,
    TaskItemProps,
    TaskItemStatus,
};
